#[test]
fn test_enginefacade_executes_plan() {
    let rt = tokio::runtime::Runtime::new().unwrap();
    let engine = EngineFacadeTddContract;
    let plan = PlanTemplate::new(
        "test".into(),
        "desc".into(),
        vec![StepDefinition::new(
            "s1".into(),
            "tool".into(),
            serde_json::json!({}),
            false,
            "desc".into(),
            None,
        )],
        None,
        HashMap::new(),
    )
    .unwrap();
    let result = rt.block_on(engine.execute(plan, None, None));
    assert!(result.is_ok());
    assert_eq!(*result.unwrap().status(), ExecutionStatus::Completed);
}

